SELECT rentabilidad_1.implementaciónventa AS implementaciónventa,   rentabilidad_1.poblacióndistribuidorgvf/gvi AS poblacióndistribuidorgvf/gvi,   SUM(rentabilidad_1.in) AS temp(calculation_0070818164712315)(1653230849)(0),   SUM(rentabilidad_1.cf) AS temp(calculation_0070818164712315)(3669921802)(0),   SUM(rentabilidad_1.totalventa) AS temp(calculation_8940818185618064)(293833081)(0),   SUM(rentabilidad_1.totalreparto) AS temp(calculation_8940818185618064)(3492347901)(0) FROM rentabilidad_1 WHERE ((rentabilidad_1.sedeforaneosintec = 'Foraneo') AND (rentabilidad_1.zona = 'NR')) GROUP BY rentabilidad_1.implementaciónventa,   rentabilidad_1.poblacióndistribuidorgvf/gvi;
